from taf.ue.pioneer.client.service import PioneerService
from taf.ue.pioneer.client.ue import UE
from taf.internal.aliasing import aliasing_scope
from taf.ue.pioneer.client.exception import PortWasOccupied, ServiceIsNotStarted, ServiceIsInvalid


class client(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    service_lookup_handler, service_store = aliasing_scope(lookup_arg='service',
                                                           lookup_type=PioneerService)

    lookup_handler, store = aliasing_scope(lookup_arg='ue',
                                           lookup_type=UE)

    def setup_service(self,
                      host,
                      port=None,
                      ssh_port=None,
                      ssh_username=None,
                      ssh_password=None,
                      timeout=None,
                      alias=None):
        """
        setup connection to the pioneer service and check if the service has been ready

        :param str host: ip address of control pc the pioneer service running on
        :param int port: port number of the pioneer service listening on
        :param str ssh_username: username for ssh connection
        :param str ssh_password: password for ssh connection
        :param int timeout: socket timeout, default timeout value for all commands.
        :param str alias: service alias

        :return: PioneerService instance

.. code-block:: Robot

        Example of Test cases:
        *********************

                *** Settings ***
        Library     taf.ue.pioneer.client       WITH NAME           client

        *** Variables ***
        ${is_kirin}    ${True}

        *** Keywords ***
        require ue
            client.setup_service
            ...    host=10.57.xxx.xxx
            ...    port=30999
            ...    ssh_username=user_name
            ...    ssh_password=password
            ...    alias=pioneer

            client.prepare_ues    service=pioneer

            client.stoplog    service=pioneer
            client.remove_remote_files    folder_path=c:/pioneer_logs/    service=pioneer

            client.startlog    logpath=C:/pioneer_logs/    logname=ta_log    service=pioneer
            client.require_ue    service=pioneer    ue_alias=mate20x
            ${is_kirin}     client.is_kirin_chip    ue=mate20x


        attach ue
            client.poweron     ue=mate20x


        detach ue
            client.poweroff    ue=mate20x

        start uplink traffic
            client.startultraffic
            ...    protocol=UDP
            ...    address=10.57.xxx.xxx
            ...    port=5001
            ...    testtime=20
            ...    bandwidth=1000
            ...    buffersize=1024
            ...    packetsize=1400
            ...    ue=mate20x


        stop uplink traffic
            client.stopultraffic    ue=mate20x

        teardown
            client.stoplog    service=pioneer
            client.release_ues    service=pioneer
            client.exportmessagedetail
            ...    exportfilename=C:/pioneer_logs/ta_log.xml
            ...    logfile=C:/pioneer_logs/ta_log-1.saf
            ...    until_timeout=120
            ...    service=pioneer
            client.teardown_service    service=pioneer


        get throughput
            client.getparammac    ue=mate20x


        *** Test Cases ***
        Test
            require ue
            detach ue
            Sleep    1
            attach ue

            start uplink traffic
            Sleep     5
            get throughput
            Sleep     5
            get throughput
            stop uplink traffic

            detach ue
            Sleep     10
            teardown

        """

        port = int(port) if port else None
        ssh_port = int(ssh_port) if ssh_port else None
        timeout = int(timeout) if timeout else None
        service = PioneerService(host,
                                 port,
                                 ssh_port=ssh_port,
                                 ssh_username=ssh_username,
                                 ssh_password=ssh_password,
                                 timeout=timeout)
        pid = service.get_pid_for_listening_port()
        if not pid:
            raise ServiceIsNotStarted()
        if not service.is_pioneer_pid(pid):
            raise PortWasOccupied("pid is {}".format(pid))

        service.setup()
        self.service_store.add(service, alias)
        return service

    @service_lookup_handler.implicit_lookup
    def teardown_service(self, service=None):
        """
        shutdown the connections

        :param Union[PioneerService, str] service: pioneer service
        """
        service.teardown()

    @service_lookup_handler.implicit_lookup
    def startlog(self, logpath, logname, until_timeout=None, service=None):
        """
        execute StartLog command to collect available logs for L1/L2/L3 as separate files by UE on control pc

        Only L3 log available for Hisillicon.
        e.g.
        UE1 log target file: logname-1.xxx
        UE2 log target file: logname-2.xxx

        :param str logpath: log folder on control pc to save logs
        :param str logname: log name prefix
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, PioneerService]] service: pioneer service
        :return: dict
        e.g.
        {
            "CMD": "StartLog",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return service.start_log(logpath, logname, timeout=until_timeout).dictionary

    @service_lookup_handler.implicit_lookup
    def stoplog(self, until_timeout=None, service=None):
        """
        execute Stoplog command to stop collecting logs

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, PioneerService]] service: pioneer service
        :return: dict
        e.g.
        {
            "CMD": "Stoplog",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return service.stop_log(timeout=until_timeout).dictionary

