    def attach(self, uemode, until_timeout=None, ue=None):
        """
        execute Attach command to attach UE on Qualcomm UE

        :param str uemode: "4G" or "5G_SA" or "5G_NSA"
        :param Optional[int] until_timeout: execution timeout in second, 60s by default
        :param Optional[Union[str, list] ue: ue under pioneer service control
        :return: dict
        {
            "CMD": "Attach",
            "EQIndex": -1, # UNION[int, list] {-1,1~n} or [1, 2,3...],
                           # -1 means all UEs, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
                 "SubStates": [0, 0, 0...]   # if EQIndex is -1, return all UE’s result.
                                             # return 0 if success, otherwise return the error codes.
            }
        }
        """
        ues = [self.store.get(ue_alias) for ue_alias in ue] if isinstance(ue, list) else [self.store.get(ue)]
        service = ues[0].service
        until_timeout = int(until_timeout) if until_timeout else None
        return service.attach(ues, uemode=uemode, until_timeout=until_timeout).dictionary

