    @lookup_handler.implicit_lookup
    def setuppdu(self, id, type, apn, ssc_mode=None, s_nssai=None, until_timeout=None, ue=None):
        """
        execute SetupPDU command to setup pdu

        :param int id: customized pdu id
        :param str type: IP type, e.g. IP, IPV6, IPV4V6
        :param str apn: apn address
        :param Optional[int] ssc_mode: e.g. 0: ssc_mode1, 1: ssc_mode2
        :param Optional[str] s_nssai: combination of sst and sd
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under pioneer service control
        :return: dict
        e.g.
        {
            "CMD": "SetupPDU",
            "EQIndex": 1,  # {1~n}, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                   "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        id = int(id)
        ssc_mode = int(ssc_mode) if ssc_mode else None

        return ue.setuppdu(id, type, apn, ssc_mode, s_nssai, until_timeout=until_timeout).dictionary

