    def starttraffic(self, protocol="UDP", address="127.0.0.1", port=5001, testtime=60, buffersize=0, packetsize=0,
                     iperftype=1, direction=0, bandwidth=0, threadcount=1, until_timeout=None, ue=None, **kwargs):
        """
        execute StartTraffic to start Link Traffic

        :param Optional[str] protocol: traffic protocol, e.g. 'UDP', 'TCP', 'UDP' by default
        :param Optional[str] address: target(e.g. app server) ip address, default '127.0.0.1'.
        :param Optional[str] port: target port NO, default 5001.
        :param Optional[str] testtime: time last for traffic in seconds, default 60.
        :param Optional[int] buffersize: buffersize in KB, default 0.
        :param Optional[int] packetsize: packetsize in Byte, default 0.
        :param Optional[int] iperftype: iperf type, e.g 0: iperf2, 1: iperf3, default 1.
        :param Optional[int] direction: traffic direction, e.g 0: UpLink, 1: DownLink, 2: both uplink and downlink directions.
        :param Optional[int] bandwidth: bandwidth in Kbps, optional if protocol is TCP, default 0.
        :param Optional[int] threadcount: tread count, default 1.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, list]] ue: ue under pioneer service control
        :param Optional kwargs: extra test parameters for uplink or downlink,
            available for 'protocol', 'address', 'port', 'testtime', 'buffersize', 'packetsize', 'iperftype',
                          'bandwidth', 'threadcount'
            add 'ul_' or 'dl_' prefix in above parameter names for uplink or downlink test configuration parameters.
            e.g:
                'ul_bandwidth', 'dl_bandwidth' for uplink and downlink 'bandwidth' config value.

        :return: dict
        return result for both directions traffic
        {
            "CMD": "StartCompositeTestPlan",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, return -1 if failure or abnormal.
                 "SubStates": [0] # if EQIndex is -1, return all UE’s’ result. return 0
                                  # if success, otherwise return the error codes.

            }
        }

        or

        {
            "CMD": "StartTraffic",
            "EQIndex": -1, # UNION[int, list] {-1,1~n} or [1, 2,3...],
                           # -1 means all UEs, 1 means the first UE, 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
                 "SubStates": [0, 0, 0...]   # if EQIndex is -1, return all UE’s result.
                                             # return 0 if success, otherwise return the error codes.
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        protocol = protocol.upper()
        port = str(port)
        testtime = str(testtime)
        bandwidth = int(bandwidth)
        buffersize = int(buffersize)
        packetsize = int(packetsize)
        iperftype = int(iperftype)
        direction = int(direction)
        threadcount = int(threadcount)
        ues = [self.store.get(ue_alias) for ue_alias in ue] if isinstance(ue, list) else [self.store.get(ue)]
        service = ues[0].service
        return service.starttraffic(ues,
                                    protocol=protocol,
                                    address=address,
                                    port=port,
                                    testtime=testtime,
                                    bandwidth=bandwidth,
                                    buffersize=buffersize,
                                    packetsize=packetsize,
                                    iperftype=iperftype,
                                    direction=direction,
                                    threadcount=threadcount,
                                    until_timeout=until_timeout,
                                    **kwargs).dictionary

    @lookup_handler.implicit_lookup
    def startultraffic(self, protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                       until_timeout=None, ue=None):
        """
        execute StartULtraffic to start Up Link Traffic

        :param str protocol: traffic protocol, e.g. 'UDP', 'TCP', 'UDP' by default
        :param str address: target(e.g. app server) ip address
        :param int port: target port NO.
        :param int testtime: time last for traffic in seconds
        :param int bandwidth: bandwidth in Kbps
        :param int buffersize: buffersize in KB
        :param int packetsize: packetsize in Byte
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under pioneer service control
        :return: dict
        {
            "CMD": "StartULtraffic",
            "EQIndex": 1, # {-1, 1~n}, -1 means all UEs, 1 means the first UE,
                          # 2 means the second UE, and so forth.
            "Param": {
                 "State": 0  # return 0 if success, otherwise return the error codes
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        port = int(port)
        testtime = int(testtime)
        bandwidth = int(bandwidth)
        buffersize = int(buffersize)
        packetsize = int(packetsize)
        return ue.startultraffic(protocol, address, port, testtime, bandwidth, buffersize, packetsize,
                                 until_timeout=until_timeout).dictionary

