    def stop_test(self, until_timeout=None, ue=None, service=None):
        """
        execute StopTest command to stop test plan which is executing now

        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under pioneer service control, default stop test process of all UEs.
        :param Optional[Union[str, PioneerService]] service: pioneer service,
                                                             if want to stop all UEs, the service is mandatory.
        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": "StopTest",
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
                  "SubStates":[0,0,0…] //if EQIndex is -1, return all UE result
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        if ue is None:
            '''
            stop all ues test process
            '''
            if service is None:
                raise ServiceIsInvalid("if 'ue' is None, the 'service' should not be None for stopping all UEs")
            service = self.service_store.get(service)
            return service.stoptest(eqindex=-1, until_timeout=until_timeout).dictionary

        ue = self.store.get(ue)
        return ue.stoptest(until_timeout=until_timeout).dictionary

