    def start_call(self, number, connecttime, duration, longcall, until_timeout=None, ue=None):
        """
        start call

        :param str number: called number.
        :param int connecttime: connection time limit(s).
        :param int duration: call duration(s).
        :param bool longcall: whether long call, true or false.
        :param Optional[int] until_timeout: execution timeout in second, 10s by default
        :param Optional[Union[str, UE]] ue: ue under pioneer service control
        :return: CommandResult
        e.g. CommandResult.dictionary
        {
            "CMD": " StartCall ",
            "EQIndex": 1, //{1, 1~n}, 1 means all UEs, 1 means the first UE,
                          //2 means the second UE, and so forth.
            "Param": {
                  "State": 0  # return 0 if success, otherwise return the error codes
                  "SubStates":[0,0,0…] //if EQIndex is -1, return all UE result
            }
        }
        """
        until_timeout = int(until_timeout) if until_timeout else None
        return ue.startcall(number=number,
                            connecttime=connecttime,
                            duration=duration,
                            longcall=longcall,
                            until_timeout=until_timeout).dictionary

